	'messages:loginreqpagetext' => 'eo:Bonvolu $1 por vidi aliajn paĝojn.',
	'messages:accmailtitle' => 'eo:La pasvorto estas sendita',
	'messages:accmailtext' => 'eo:Hazarde generita pasvorto por [[User talk:$1|$1]] estas sendita al $2.

